1: import React from 'react';
2: import { Button } from '@carbon/react';
3: import { useTranslation } from 'react-i18next';
4: import {
5:   AddIcon,
6:   launchWorkspace2,
7:   openmrsFetch,
8:   restBaseUrl,
9:   showModal,
10:   showSnackbar,
11:   useConfig,
12:   useLayoutType,
13:   type FetchResponse,
14:   type Order,
15:   type Visit,
16:   type Workspace2DefinitionProps,
17: } from '@openmrs/esm-framework';
18: import styles from './fill-prescription-button.scss';
19: import { type PharmacyConfig } from '../config-schema';
20: 
21: const FillPrescriptionButton: React.FC<{}> = () => {
22:   const isTablet = useLayoutType() === 'tablet';
23:   const responsiveSize = isTablet ? 'lg' : 'md';
24:   const { t } = useTranslation();
25:   const { drugOrderTypeUUID } = useConfig<PharmacyConfig>();
26: 
27:   const launchSearchWorkspace = () => {
28:     launchWorkspace2(
29:       'dispensing-patient-search-workspace',
30:       {
31:         workspaceTitle: t('fillPrescriptionForPatient', 'Fill prescription for patient'),
32:         onPatientSelected(
33:           patientUuid: string,
34:           patient: fhir.Patient,
35:           launchChildWorkspace: Workspace2DefinitionProps['launchChildWorkspace'],
36:           closeWorkspace: Workspace2DefinitionProps['closeWorkspace'],
37:         ) {
38:           getActiveVisitsForPatient(patientUuid).then(async (response) => {
39:             const activeVisit = response.data.results?.[0];
40:             if (activeVisit) {
41:               await closeWorkspace();
42:               launchWorkspace2(
43:                 'dispensing-order-basket-workspace',
44:                 {},
45:                 {
46:                   patientUuid: patientUuid,
47:                   patient: patient,
48:                   visitContext: activeVisit,
49:                   drugOrderWorkspaceName: 'dispensing-order-basket-add-drug-order-workspace',
50:                   allergyFormWorkspaceName: 'dispensing-order-basket-add-allergy-workspace',
51:                   visibleOrderPanels: [drugOrderTypeUUID],
52:                   onOrderBasketSubmitted: (encounterUuid: string, _: Array<Order>) => {
53:                     showModal('on-prescription-filled-modal', {
54:                       patient,
55:                       encounterUuid,
56:                     });
57:                   },
58:                 },
59:               );
60:             } else {
61:               showSnackbar({
62:                 title: t('visitRequired', 'Visit required'),
63:                 subtitle: t(
64:                   'visitRequiredForPatientToFillPrescription',
65:                   'Visit required for patient to fill prescription',
66:                 ),
67:                 kind: 'error',
68:               });
69:             }
70:           });
71:         },
72:       },
73:       {
74:         startVisitWorkspaceName: 'dispensing-start-visit-workspace',
75:       },
76:     );
77:   };
78: 
79:   return (
80:     <div className={styles.buttonContainer}>
81:       <Button
82:         kind="primary"
83:         renderIcon={(props) => <AddIcon size={16} {...props} />}
84:         size={responsiveSize}
85:         onClick={launchSearchWorkspace}>
86:         {t('fillPrescription', 'Fill prescription')}
87:       </Button>
88:     </div>
89:   );
90: };
91: 
92: function getActiveVisitsForPatient(
93:   patientUuid: string,
94:   abortController?: AbortController,
95:   v?: string,
96: ): Promise<FetchResponse<{ results: Array<Visit> }>> {
97:   const custom = v ?? `default`;
98: 
99:   return openmrsFetch(`${restBaseUrl}/visit?patient=${patientUuid}&v=${custom}&includeInactive=false`, {
100:     signal: abortController?.signal,
101:     method: 'GET',
102:     headers: {
103:       'Content-type': 'application/json',
104:     },
105:   });
